preConditionHook:
// Within the same window a failed breakout has occurred on BOTH sides of the
// range -- bears trapped below and bulls trapped above -- so the next genuine
// breakout in either direction is expected to travel further than usual.
//
// The single-sided test is FailedBreakoutReversal, already in the corpus, and
// this rule INLINES that rule's loop verbatim rather than inventing a second
// spelling of the same thing (the corpus's rule for composites that are named
// setups: keep the dependency in the row text, inline the parts in code). For
// each candidate breakout bar k the level is the extreme of bars
// k+1 .. k+rangeLookback, open-coded because Lowest(l, rangeLookback)[k + 1]
// is a history reference on a function call at a VARIABLE offset; Extremes(),
// which Highest and Lowest call, is EL source and is exactly this loop --
// seed at the first bar of the window and scan the rest with a strict,
// tolerance-carrying comparison, hence el_gt / el_lt and not raw > and <.
//
// NOT a composition of two placements. The pane system ANDs entry rules, but
// each placement carries ONE side, so "the long-side failure AND the
// short-side failure, both true on this bar" cannot be built by stacking two
// placements of FailedBreakoutReversal. Direction-agnostic by construction,
// so both sides carry the same text.
//
// Both directions are accumulated on every candidate, matching EL's
// non-short-circuiting evaluation; the loop runs unconditionally.
brokeDown = false;
brokeUp = false;
for (int k = 1; k <= (int)reentryWindow; ++k) {
    double lvlLow = low[k + 1];
    double lvlHigh = high[k + 1];
    for (int j = k + 2; j <= k + (int)rangeLookback; ++j) {
        if (el_lt(low[j], lvlLow)) lvlLow = low[j];
        if (el_gt(high[j], lvlHigh)) lvlHigh = high[j];
    }
    if (el_lt(close[k], lvlLow) && el_gt(close[0], lvlLow)) brokeDown = true;
    if (el_gt(close[k], lvlHigh) && el_lt(close[0], lvlHigh)) brokeUp = true;
}
bothFailed = brokeDown && brokeUp;
